// Package postgres implements the settings repository with the queries in
// queries.sql (generated by sqlc into sqlcgen/).
package postgres

import (
	"context"
	"errors"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"

	"github.com/AtmosferaSoltec/atm-km-api/internal/modules/settings/adapters/postgres/sqlcgen"
	"github.com/AtmosferaSoltec/atm-km-api/internal/modules/settings/domain"
	"github.com/AtmosferaSoltec/atm-km-api/internal/platform/tx"
)

// DB gives the ongoing transaction's connection, or the pool (tx.Runner).
type DB interface {
	DB(ctx context.Context) tx.DBTX
}

// Repository implements app.Repository.
type Repository struct {
	db DB
}

// NewRepository creates the repository.
func NewRepository(db DB) Repository { return Repository{db: db} }

func (r Repository) q(ctx context.Context) *sqlcgen.Queries { return sqlcgen.New(r.db.DB(ctx)) }

// Ensure creates the default row if missing and returns the settings.
func (r Repository) Ensure(ctx context.Context, userID uuid.UUID) (domain.Settings, error) {
	q := r.q(ctx)
	if err := q.EnsureSettings(ctx, userID); err != nil {
		return domain.Settings{}, err
	}
	row, err := q.GetSettings(ctx, userID)
	if err != nil {
		return domain.Settings{}, err
	}
	return toSettings(row), nil
}

// UpdateRates stores new rates.
func (r Repository) UpdateRates(ctx context.Context, userID uuid.UUID, rates domain.Rates) (domain.Settings, error) {
	row, err := r.q(ctx).UpdateRates(ctx, sqlcgen.UpdateRatesParams{
		UserID: userID, GasolineRate: rates.Gasoline, LpgRate: rates.LPG, WearRate: rates.Wear,
	})
	return toSettings(sqlcgen.GetSettingsRow(row)), err
}

// RotateShareToken stores a new share token.
func (r Repository) RotateShareToken(ctx context.Context, userID, token uuid.UUID) (domain.Settings, error) {
	row, err := r.q(ctx).RotateShareToken(ctx, sqlcgen.RotateShareTokenParams{UserID: userID, ShareToken: token})
	return toSettings(sqlcgen.GetSettingsRow(row)), err
}

// ByShareToken finds the settings carrying token.
func (r Repository) ByShareToken(ctx context.Context, token uuid.UUID) (domain.Settings, error) {
	row, err := r.q(ctx).GetSettingsByShareToken(ctx, token)
	if errors.Is(err, pgx.ErrNoRows) {
		return domain.Settings{}, domain.ErrNotFound
	}
	if err != nil {
		return domain.Settings{}, err
	}
	return toSettings(sqlcgen.GetSettingsRow(row)), nil
}

func toSettings(row sqlcgen.GetSettingsRow) domain.Settings {
	return domain.Settings{
		UserID:     row.UserID,
		Rates:      domain.Rates{Gasoline: row.GasolineRate, LPG: row.LpgRate, Wear: row.WearRate},
		ShareToken: row.ShareToken,
	}
}
